export declare function updateVersion(): void;
/** Files that reload the process when they changed (not HMR available) */
export declare function addReloadFile(path: string): void;
/** Reload the current process */
export declare function reloadProcess(): void;
export declare function startProcess(mainEntry: string, importer: string): void;
